package com.supersports.reviews;
import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import org.springframework.web.client.RestClient;import org.springframework.web.client.RestClientException;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/v1") class ReviewsController{
 private final ReviewsRepository repo;private final RestClient orders;
 ReviewsController(ReviewsRepository repo,@Value("${orders.base-url}")String url){this.repo=repo;orders=RestClient.builder().baseUrl(url).build();}
 @GetMapping("/reviews/products/{productId}") List<Map<String,Object>> published(@PathVariable UUID productId){return repo.published(productId);}
 @GetMapping("/reviews/products/summaries") List<Map<String,Object>> summaries(@RequestParam List<UUID> productIds){try{return repo.summaries(DemoReviews.products(productIds));}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,e.getMessage());}}
 @PostMapping("/operator/reviews/demo-seed") Map<String,Object> seed(@RequestBody DemoSeed request,@AuthenticationPrincipal Jwt jwt){
  if(request==null)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Invalid demo seed");
  try{return repo.seed(request.operationId(),jwt.getSubject(),request.productIds(),request.reviewsPerProduct());}
  catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,e.getMessage());}
  catch(IllegalStateException e){throw new ResponseStatusException(HttpStatus.CONFLICT,e.getMessage());}
 }
 record DemoSeed(UUID operationId,List<UUID> productIds,int reviewsPerProduct){}
 @PostMapping("/customer/reviews") ResponseEntity<Map<String,Object>> submit(@RequestBody ReviewRequest request,@AuthenticationPrincipal Jwt jwt){if(request==null||request.orderId()==null||request.productId()==null||request.skuId()==null)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Invalid review");try{var proof=orders.get().uri("/api/v1/orders/{order}/verified-purchase/{sku}",request.orderId(),request.skuId()).headers(h->h.setBearerAuth(jwt.getTokenValue())).retrieve().body(Map.class);if(proof==null||!Boolean.TRUE.equals(proof.get("verified"))||!request.productId().toString().equals(String.valueOf(proof.get("productId"))))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Delivered purchase could not be verified");return ResponseEntity.status(HttpStatus.CREATED).body(repo.submit(UUID.randomUUID(),jwt.getSubject(),request.orderId(),request.productId(),request.skuId(),request.rating(),request.title(),request.body()));}catch(org.springframework.web.client.HttpClientErrorException.NotFound e){throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Owned delivered purchase not found");}catch(org.springframework.web.client.HttpClientErrorException.UnprocessableEntity e){throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Purchase is not delivered");}catch(RestClientException e){throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Order verification is unavailable");}catch(IllegalStateException e){throw new ResponseStatusException(HttpStatus.CONFLICT,e.getMessage());}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Invalid review fields");}}
 @GetMapping("/customer/reviews") List<Map<String,Object>> mine(@AuthenticationPrincipal Jwt jwt){return repo.mine(jwt.getSubject());}
 @GetMapping("/operator/reviews/pending") List<Map<String,Object>> queue(){return repo.queue();}
 @GetMapping("/operator/reviews") List<Map<String,Object>> moderationRows(@RequestParam(defaultValue="PENDING")String state,@RequestParam(required=false)UUID productId){if(!Set.of("PENDING","PUBLISHED","REJECTED","HIDDEN").contains(state))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Invalid review state");return repo.moderationRows(state,productId);}
 @PostMapping("/operator/reviews/{id}/moderation") Map<String,Object> moderate(@PathVariable UUID id,@RequestBody Moderation request,@AuthenticationPrincipal Jwt jwt){if(request==null||request.operationId()==null)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY);try{return repo.moderate(id,request.state(),jwt.getSubject(),request.reason(),request.operationId());}catch(NoSuchElementException e){throw new ResponseStatusException(HttpStatus.NOT_FOUND);}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Invalid moderation request");}catch(IllegalStateException e){throw new ResponseStatusException(HttpStatus.CONFLICT,e.getMessage());}}
 record ReviewRequest(UUID orderId,UUID productId,UUID skuId,int rating,String title,String body){} record Moderation(String state,String reason,UUID operationId){}
}
